// Saca el texto del email que manda el formulario de la web y le pide a Gemini los datos.
const instrucciones = `Te paso un email que ha generado el formulario de contacto de la web de una instaladora solar.
Saca los datos de la PERSONA que ha escrito y devuelve SOLO un JSON con estas claves:
{"nombre": "", "telefono": "", "email": "", "localidad": "", "interes": "", "mensaje": ""}
Reglas:
- "interes": en pocas palabras, qué pide (por ejemplo "bombeo solar para un pozo", "placas para casa").
- "mensaje": lo que ha escrito, resumido en una o dos frases si es largo.
- El teléfono y el email son los de la persona que escribe, NO los de la empresa ni los de la web.
- Si un dato no aparece, déjalo vacío. No inventes nada.`;

return $input.all().map((item) => {
  const e = item.json;
  const texto = String(e.text || e.textAsHtml || e.snippet || '').slice(0, 6000);
  return {
    json: {
      asuntoOriginal: e.subject || '',
      textoOriginal: texto,
      peticion: {
        contents: [{ parts: [{ text: `${instrucciones}\n\nASUNTO: ${e.subject || ''}\n\nEMAIL:\n${texto}` }] }],
        generationConfig: { temperature: 0, responseMimeType: 'application/json' },
      },
    },
  };
});

// ===== AJUSTES DEL CLIENTE =====
const EMPRESA = 'Fercam';
const SALUDO_WHATSAPP = (nombre) =>
  `Hola${nombre ? ' ' + nombre.split(' ')[0] : ''}, soy de ${EMPRESA}. Hemos recibido tu consulta en la web. ¿Cuándo te viene bien que hablemos?`;
// ================================

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const hoy = () => new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Madrid' });   // "2026-10-07"
// Acepta "2026-10-07" y "07/10/2026" (por si la hoja cambia el formato)
const aDia = (s) => {
  s = String(s ?? '').trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return Date.UTC(+m[1], m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); if (m) return Date.UTC(+m[3], m[2] - 1, +m[1]);
  return null;
};
const diasDesde = (s) => { const d = aDia(s), h = aDia(hoy()); return d == null ? null : Math.round((h - d) / 864e5); };
const waNumero = (t) => { let d = String(t ?? '').replace(/\D/g, ''); if (d.startsWith('0034')) d = d.slice(2); if (d.length === 9) d = '34' + d; return d.length >= 11 ? d : ''; };
const enlaceWA = (tel, texto) => { const n = waNumero(tel); return n ? `https://wa.me/${n}?text=${encodeURIComponent(texto)}` : ''; };
const emailValido = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(e ?? '').trim());

const pedidos = $('Preparar petición a Gemini').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);

// Lo que ha entendido Gemini. Si falla, sacamos al menos el teléfono del texto.
function datosDe(k) {
  const txt = respuestas[k]?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
  try { return { ...JSON.parse(txt.replace(/^```(json)?|```$/g, '').trim()), ia: true }; } catch { return { ia: false }; }
}
const telefonoEn = (t) => (String(t).match(/(?:\+?34[\s.-]?)?[6789](?:[\s.-]?\d){8}/) || [''])[0];

return pedidos.map((p, k) => {
  const d = datosDe(k);
  const nombre = String(d.nombre || '').trim();
  const telefono = String(d.telefono || telefonoEn(p.textoOriginal)).trim();
  const email = emailValido(d.email) ? String(d.email).trim().toLowerCase() : '';
  const mensaje = String(d.mensaje || (d.ia ? '' : p.textoOriginal.slice(0, 300))).trim();
  const wa = enlaceWA(telefono, SALUDO_WHATSAPP(nombre));
  const titulo = `Nuevo contacto: ${nombre || 'sin nombre'}`;
  const filas = [['Teléfono', telefono], ['Email', email], ['Localidad', d.localidad], ['Qué pide', d.interes]].filter(([, v]) => v);
  const avisoIA = d.ia ? '' : 'La IA no ha podido leer el email: revisa el original en el correo.';

  let telegram = `<b>${esc(titulo)}</b>\n` + filas.map(([a, b]) => `<b>${a}:</b> ${esc(b)}`).join('\n');
  if (mensaje) telegram += `\n\n<i>${esc(mensaje)}</i>`;
  if (avisoIA) telegram += `\n\n<i>(${esc(avisoIA)})</i>`;
  if (wa) telegram += `\n\n<a href="${esc(wa)}">Contestar por WhatsApp</a>`;

  const html = `<p><strong>${esc(titulo)}</strong></p>
<table cellpadding="4">${filas.map(([a, b]) => `<tr><td><strong>${a}</strong></td><td>${esc(b)}</td></tr>`).join('')}</table>
${mensaje ? `<p style="color:#555">${esc(mensaje)}</p>` : ''}${avisoIA ? `<p style="color:#a00">${esc(avisoIA)}</p>` : ''}
${wa ? `<p><a href="${esc(wa)}" style="display:inline-block;background:#25d366;color:#fff;padding:10px 18px;border-radius:20px;text-decoration:none;font-weight:bold">Contestar por WhatsApp</a></p>` : ''}`;

  const fila = {
    'ID': `${Date.now().toString(36)}-${k}`, 'Fecha': hoy(), 'Nombre': nombre, 'Teléfono': telefono, 'Email': email,
    'Localidad': d.localidad || '', 'Qué pide': d.interes || '', 'Mensaje': mensaje,
    'Estado': 'nuevo', 'Estado visto': 'nuevo', 'Estado desde': hoy(), 'Recordatorio enviado': '', 'Aviso enviado': '', 'Notas': '',
  };
  return { json: { asunto: titulo, telegram, html, fila } };
});

